    var command = 'xdg-mime query default x-scheme-handler/http';

    exec(command, function (err, stdout, stderr) {
        if(err) {
            callback('Unable to execute the query: ' + err + '\n' + stderr);
            return;
        }

        var value = stdout;

        /*
         *  ubuntu 14.04.1:
         *  --------
         *  firefox.desktop
         *  google-chrome.desktop
         *  chromium-browser.desktop
         *  opera.desktop
